-- RAEL'S TRICKS - OBFUSCATED LOADER
local encoded = [[]]
local decoded = table.create(#encoded / 2)
for i = 1, #encoded, 2 do
    local byte = tonumber(encoded:sub(i, i + 1), 16)
    decoded[#decoded + 1] = string.char((byte - 97) % 256)
end
local chunk, compileError = loadstring(table.concat(decoded))
if not chunk then error(compileError) end
local ok, runError = pcall(chunk)
if not ok then error(runError) end
